   359→#[cfg(test)]
   360→mod test {
   361→    use super::*;
   362→    use crate::config::Config as NetworkConfig;
   363→    use types::{Epoch, MainnetEthSpec};
   364→
   365→    type E = MainnetEthSpec;
   366→    const TEST_NFD: [u8; 4] = [0x01, 0x02, 0x03, 0x04];
   367→
   368→    fn make_fulu_spec() -> ChainSpec {
   369→        let mut spec = E::default_spec();
   370→        spec.fulu_fork_epoch = Some(Epoch::new(10));
   371→        spec
   372→    }
   373→
   374→    fn build_enr_with_config(
   375→        config: NetworkConfig,
   376→        cgc: Option<u64>,
   377→        spec: &ChainSpec,
   378→    ) -> (Enr, CombinedKey) {
   379→        let keypair = libp2p::identity::secp256k1::Keypair::generate();
   380→        let enr_key = CombinedKey::from_secp256k1(&keypair);
   381→        let enr_fork_id = EnrForkId::default();
   382→        let enr = build_enr::<E>(&enr_key, &config, &enr_fork_id, cgc, TEST_NFD, spec).unwrap();
   383→        (enr, enr_key)
   384→    }
